def tri(n):
    def tribonacci_helper(n, memo):
        if n in memo:
            return memo[n]
        if n == 1:
            return 3
        elif n % 2 == 0:
            result = 1 + n / 2
        else:
            result = tribonacci_helper(n - 1, memo) + tribonacci_helper(n - 2, memo) + tribonacci_helper(n + 1, memo)
        memo[n] = result
        return result

    memo = {}
    return [tribonacci_helper(i, memo) for i in range(n + 1)]
